/* earth-textures.js — offline globe textures as data URIs (file:// safe).
 * Data URIs are CORS-clean, so WebGL texImage2D accepts them where local
 * file:// images would be rejected as cross-origin.
 *
 * Sources (NASA Blue Marble, free to use with attribution):
 *   day:  NASA Blue Marble (three-globe example/img/earth-blue-marble.jpg,
 *         4096x2048) downscaled to 2048x1024 JPEG q78.
 *   topo: NASA topology/bump map (three-globe example/img/earth-topology.png,
 *         2048x1024) re-encoded JPEG q85.
 *   Credit: Image courtesy NASA Earth Observatory (https://earthobservatory.nasa.gov)
 *   Pinned source: three-globe example assets as of globe.gl 2.46.2 integration.
 *
 * Exposes: window.EARTH_TEXTURES = { day: 'data:image/jpeg;base64,...',
 *                                    topo: 'data:image/jpeg;base64,...' }
 */
(function () {
  'use strict';
  window.EARTH_TEXTURES = {
    day: 'data:image/jpeg;base64,',
    topo: 'data:image/jpeg;base64,'
  };
})();
